import unittest
from hourglass.rounding import round_labels, round_span
from hourglass.models import Span

class RoundSpanTests(unittest.TestCase):
    def test_snaps_to_nearest_step(self):
        result = round_span(Span(543, 1027), 15)
        self.assertEqual(result, Span(540, 1020))

    def test_ties_round_up(self):
        result = round_span(Span(45, 95), 10)
        self.assertEqual(result, Span(50, 100))

    def test_hour_step(self):
        result = round_span(Span(500, 1000), 60)
        self.assertEqual(result, Span(480, 1020))

    def test_collapsed_span_is_rejected(self):
        with self.assertRaises(ValueError):
            round_span(Span(541, 545), 15)

class LabelTests(unittest.TestCase):
    def test_label_format(self):
        labels = round_labels([Span(541, 1034)], 15)
        self.assertEqual(
            labels, ["09:00-17:15 (8h 15m)"]
        )

    def test_one_label_per_span(self):
        spans = [Span(60, 120), Span(600, 660)]
        self.assertEqual(len(round_labels(spans, 5)), 2)

    def test_empty_list(self):
        self.assertEqual(round_labels([], 15), [])

class BadStepTests(unittest.TestCase):
    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 90):
            with self.assertRaises(ValueError):
                round_labels([Span(60, 120)], step)

    def test_bad_step_with_no_spans(self):
        with self.assertRaises(ValueError):
            round_labels([], 0)
